*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#17324d;margin:0}.mfc{max-width:980px;margin:auto;padding:24px 18px 48px}
.brand{text-align:center;font:700 italic 34px Georgia,serif;color:#173F63}.brand b{color:#d6a400}h1{text-align:center;color:#173F63;margin:7px 0;font-size:28px}.sub{text-align:center;font-weight:700}
.actions{text-align:center;margin:16px 0 26px}.pdfbtn{display:inline-block;background:#173F63;color:#fff!important;text-decoration:none;padding:11px 18px;border-radius:8px;font-weight:700}
.q{border:1px solid #d8e2ea;border-radius:12px;padding:18px;margin:18px 0}.q h2{font-size:19px;margin:0 0 10px}.q p{font-size:17px;line-height:1.55}.visual{background:#F8FBFD;border:1px solid #dce7ee;border-radius:10px;padding:18px;margin:14px 0}
.receipt{max-width:330px;margin:auto;background:#fff;padding:16px;font-family:monospace;line-height:1.8;border:1px dashed #777}.ruler{display:flex;align-items:flex-end;justify-content:space-between;border-bottom:4px solid #173F63;padding-top:30px}.ruler i,.ruler b{height:18px;border-left:2px solid #173F63;padding-top:20px}.ruler b{height:30px;color:#c75c45}
.scale{text-align:center}.screen{display:inline-block;background:#263238;color:#9df29d;font:700 28px monospace;padding:14px 30px;border-radius:8px}.base{width:220px;height:16px;background:#9aa9b2;margin:auto;border-radius:0 0 20px 20px}
.labels,.cards,.calcchoices,.shop{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}.labels span,.cards span,.calcchoices span,.shop span{background:#fff;border:2px solid #2f75a8;border-radius:9px;padding:14px 18px;text-align:center}
.vertical{font:20px monospace;max-width:170px;margin:auto;text-align:right;background:#fff;padding:12px}.vertical span{display:block}.podium{display:flex;gap:10px;align-items:flex-end;justify-content:center}.podium div{width:110px;background:#fff;border:2px solid #b9cad7;border-radius:8px;padding:12px;text-align:center}
.tank{width:120px;height:170px;border:4px solid #173F63;border-top:0;margin:auto;position:relative;display:flex;justify-content:center;align-items:center}.water{position:absolute;bottom:0;left:0;right:0;background:#8FC4E5}.tank b,.tank small{z-index:2;background:#ffffffcc;padding:4px}.tank small{position:absolute;bottom:8px}
.machine{display:flex;align-items:center;justify-content:center;gap:18px}.machine span{border:2px solid #2f75a8;background:#fff;padding:15px 25px;border-radius:8px;font-size:22px}.machine b{background:#F4D58D;padding:15px;border-radius:50%}
.pricecard,.ticket{max-width:300px;margin:auto;background:#fff;border:2px dashed #2f75a8;padding:18px;text-align:center}.pricecard>* ,.ticket>*{display:block;margin:7px}.pricecard strong,.ticket strong{font-size:24px}
.tape{height:55px;border:2px solid #173F63;display:flex;max-width:700px;margin:auto}.tape span,.tape i{display:flex;align-items:center;justify-content:center;font-style:normal}.tape span:first-child{background:#8FC4E5}.tape span:nth-child(2){background:#F4D58D}.tape i{flex:1}
.calculator{display:flex;justify-content:center;align-items:center;gap:8px;font:700 22px monospace}.calculator div{background:#263238;color:#a8f0a8;padding:12px}.calculator button{padding:10px}
.hundred{display:grid;grid-template-columns:repeat(10,20px);gap:2px;justify-content:center}.hundred i{width:20px;height:20px;border:1px solid #173F63;background:#fff}.hundred i.on{background:#8FC4E5}
.bottles{display:flex;align-items:center;justify-content:center;gap:9px;flex-wrap:wrap}.bottles .jug{padding:18px;border:3px solid #173F63;border-top:0}.bottles span{width:25px;height:55px;border:2px solid #2f75a8;border-radius:5px 5px 9px 9px;background:#fff}
.safe{max-width:280px;margin:auto;background:#5e6a70;border:8px solid #444;border-radius:10px;padding:20px;text-align:center}.safe div{background:#dce8d5;font:700 28px monospace;padding:12px}
.solar{display:flex;justify-content:center;align-items:center;gap:20px;flex-wrap:wrap}.solar span{width:110px;height:90px;border-radius:50%;background:#fff;border:2px solid #d5b45a;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:22px}.solar b{font-size:16px}
.lines{height:48px;border-bottom:1px dashed #b9c7d2}.opts{display:flex;gap:10px;flex-wrap:wrap}.opt{border:1px solid #b9cad7;border-radius:7px;padding:8px 14px}
.gab{margin-top:32px}.gab details{border:1px solid #c8dce9;border-radius:10px;overflow:hidden}.gab summary{background:#173F63;color:#fff;padding:13px 18px;font-size:18px;font-weight:700;cursor:pointer;display:flex;justify-content:space-between}.inside{padding:14px 18px;background:#f7fafc}
@media(max-width:650px){.podium{display:grid;grid-template-columns:1fr 1fr}.hundred{grid-template-columns:repeat(10,16px)}.hundred i{width:16px;height:16px}}@media print{.actions,.gab{display:none}}
